      "赤穗熊骑": "فارس الدببة للسنبلة الحمراء",
      "麦田稻草魔像": "غولم القش في حقل القمح",
      "留守的农民夫妇": "الزوجان المزارعان اللذان بقيا",
      "别紧张，年轻人。那些熊没有杀害这里的人。它们来到农场后，只把原来的村民赶去了王城方向。": "على مهلك يا فتى. تلك الدببة لم تقتل أحدًا هنا. حين جاءت إلى المزرعة لم تفعل سوى طرد القرويين نحو العاصمة الملكية.",
      "我们留下，是因为没有从它们身上感到敌意。最初它们连犁怎么扶都不知道，只会用蛮力把田翻得乱七八糟。": "بقينا لأننا لم نشعر منها بأي عداء. في البداية لم تكن تعرف حتى كيف تمسك المحراث — كانت تقلب الحقول فوضى بالقوة الغاشمة.",
      "后来我们教熊男修水渠、播麦种，也教熊娘照料蜂箱和收割。它们学得很慢，但从不糟蹋粮食。": "ثم علّمنا ذكور الدببة إصلاح القنوات وبذر القمح، وعلّمنا إناثها رعاية الخلايا وجني المحصول. يتعلمون ببطء، لكنهم لا يهدرون الطعام أبدًا.",
      "它们会在谷仓里给幼熊留出最暖的位置，也会把第一袋新麦送到我们门口。至少在我们眼里，它们没有传闻中那么可恶。": "يحجزون أدفأ مكان في الحظيرة لصغارهم، ويحضرون أول كيس من القمح الجديد إلى بابنا. على الأقل في أعيننا، ليسوا بالسوء الذي تقوله الشائعات.",
      "若你一定要继续往前，就亲眼看看再作判断吧。这里发生的事，也许并不是简单的怪物占领村庄。": "إن كان لا بد أن تمضي، فانظر بعينيك قبل أن تحكم. ما حدث هنا قد لا يكون مجرد وحوش استولت على قرية.",
      "露珠幼母": "أم حضنة قطرة الندى",
