      "让亡者也能申诉和立契的王国法庭": "بلاط ملكي يحق فيه حتى للموتى تقديم العرائض وتوقيع العقود",
      "月林精灵": "جان غابة القمر",
      "公共林地、识字学校与巡林员制度": "غابات عامة ومدارس محو أمية ونظام الجوّالين",
