      "护林法、共享牧道与边地自治议会": "قوانين حماية الغابات وطرق رعي مشتركة ومجالس حكم ذاتي حدودية",
      "机巧侏儒": "جنوم الآليات",
      "专利制度、公开船坞与事故追责": "أنظمة براءات الاختراع وأحواض سفن مفتوحة ومحاسبة على الحوادث",
      "虚空观测站": "مرصد الفراغ",
      "用长期观测区分天启、幻觉和噪声": "رصد طويل الأمد للتمييز بين الوحي والوهم والضجيج",
      "黄金狮鹫族": "الغريفين الذهبية",
      "空骑军籍、兽族居住权与救援航线": "تجنيد فرسان السماء وإقامة شعوب الوحوش وطرق طيران الإنقاذ",
      "我加入王国不是为了变成人类，而是因为这里允许我保留自己，也允许我凭本事向前。": "لم أنضم إلى المملكة لأصير بشريًا، بل لأنني هنا أستطيع أن أبقى نفسي وأتقدم بجدارتي.",
      "血统只决定出生，制度和选择才决定我们能否并肩站在这里。": "النسب يقرر فقط أين نولد؛ أما المؤسسات والاختيارات فتقرر إن كنا نستطيع الوقوف جنبًا إلى جنب هنا.",
      "今天我代表的不是归顺，而是一个异族也能公开竞争、堂堂正正赢得掌声的王国。": "اليوم لا أمثّل الخضوع، بل مملكة تستطيع فيها الأعراق الأخرى التنافس علنًا ونيل التصفيق بعدل.",
      "漂亮。能把我逼到这里，说明王都接纳的也确实是一位值得尊敬的对手。": "جميل. أن تدفعني إلى هذا الحد يثبت أن العاصمة ترحب حقًا بخصم جدير بالاحترام.",
      "我不会替那些偏见证明异族只配躲在荒野。来，最后一轮！": "لن أثبت صحة تلك الأحكام المسبقة بأن الأعراق الأخرى مكانها الاختباء في البراري. هيا — الجولة الأخيرة!",
      "你赢了。愿这座竞技场继续证明：人类与异族可以争胜，却不必彼此仇恨。": "فزتَ. لتواصل هذه الساحة إثبات ذلك: البشر والأعراق الأخرى يستطيعون التنافس دون أن يكره بعضهم بعضًا.",
      "出牌再快一点。观众买票不是来看你思考人生的。": "العب أسرع. الجمهور لم يشترِ التذاكر ليشاهدك تتأمل في الحياة.",
      "你管这叫战线？我家的晾衣绳都比它更难突破。": "تسمي هذا خط قتال؟ حبل غسيلي أصعب اختراقًا.",
      "放心，我会给你留点体面——至少等裁判宣布以后再笑。": "اطمئن، سأترك لك بعض الكرامة — سأنتظر على الأقل صافرة الحكم قبل أن أضحك.",
      "别看记分牌了，它不会因为你盯得够久就站到你那边。": "كفّ عن النظر إلى لوحة النتائج. لن تغيّر جانبها لمجرد أنك تحدّق فيها طويلًا.",
      "刚才那一下还算像样。不过想让我闭嘴，你还差最后一段路。": "الحركة الأخيرة كانت لا بأس بها. لكن لتُسكتني، ما زال أمامك شوط أخير.",
      "别急着向观众挥手！我只是把翻盘留到最吵的时候。": "لا تلوّح للجمهور بعد! أنا فقط أدّخر عودتي لأعلى لحظة صخب.",
      "今天算你赢。下次我会先击败你，再投诉这块明显偏向你的地板。": "تفوز اليوم. في المرة القادمة سأهزمك أولًا، ثم أقدّم شكوى على هذه الأرضية التي تحابيك بوضوح.",
      "别介意，我正在记录你的出牌习惯。真正危险的数据，往往来自自信的人。": "لا تبالِ بي، أسجّل عادات لعبك. البيانات الخطيرة حقًا تأتي غالبًا من الواثقين.",
      "每次交换都在缩小答案范围。再过几轮，你的选择就会只剩一种。": "كل مبادلة تضيّق الإجابة. بضع جولات أخرى ولن يبقى لك إلا خيار واحد.",
      "竞技场比实验室诚实：错误的理论会当场掉血。": "الساحة أصدق من المختبر: النظريات الخاطئة تخسر الصحة في الحال.",
      "放心，若你击败我，我会如实把结论写进报告。": "اطمئن، إن هزمتني فسأكتب الخلاصة في تقريري بأمانة.",
      "数据偏离预测了。很好，没有意外的研究才最无聊。": "البيانات تنحرف عن التوقع. جيد — البحث بلا مفاجآت هو الأكثر مللًا.",
      "样本正在反过来验证研究者……我承认这个结果很有说服力。": "العيّنة تتحقق الآن من الباحث... أعترف أن هذه النتيجة مقنعة جدًا.",
      "结论成立：你的临场判断胜过我的模型。下一版论文会写上这一条。": "الخلاصة مؤكدة: حكمك اللحظي يتفوق على نموذجي. المسودة التالية لبحثي ستقول ذلك.",
      "竞技场没有真正的仇敌，只有愿意把本领摆到阳光下的人。": "لا أعداء حقيقيين في الساحة، بل أناس مستعدون لإظهار مهاراتهم في ضوء الشمس.",
      "别为保存生命而放弃阵线。荣誉来自承担风险，不是躲过风险。": "لا تترك الخط لتنجو بحياتك. الشرف يأتي من خوض المخاطر، لا من تجنبها.",
      "观众记得胜负，战士应当记得自己在压力下做过什么选择。": "الجمهور يتذكر النتيجة؛ أما المحارب فعليه أن يتذكر الخيارات التي اتخذها تحت الضغط.",
      "无需留手。尊重对手最好的方式，就是拿出真正想赢的力量。": "لا تتمالك نفسك. أفضل طريقة لاحترام الخصم أن تأتي بالقوة التي تريد الفوز حقًا.",
      "好一记正面突破。疼痛会过去，失去判断才是真正的败势。": "اختراق أمامي بارع. الألم يزول؛ فقدان الحكم هو الهزيمة الحقيقية.",
      "只剩最后一点生命，正好用来检验最后一点意志。": "بقيت نقطة صحة أخيرة — مثالية لاختبار آخر ذرة من الإرادة.",
      "胜负已定。我记住了你的战术，也会把掌声留给配得上它的人。": "حُسمت المباراة. حفظتُ تكتيكاتك، وسأدّخر تصفيقي لمن يستحقه.",
      "并": "و",
      "，它们可以立即攻击": "، ويمكنها الهجوم فورًا",
      "和": "و",
      "永久": "بشكل دائم",
      "本回合": "هذا الدور",
