      "直面狼王": "واجه ملك الذئاب",
      "第五关位于翡翠城南方的古城废墟。灰狼与其他野兽凭借速度和突袭扩张领地，最终迎战银灰狼女猎手。": "يقع الفصل 5 في الأطلال القديمة جنوب المدينة الزمردية. تتوسع الذئاب الرمادية والوحوش الأخرى في أراضيها بالسرعة والكمائن؛ وفي النهاية تواجه صيادة الذئاب الفضية الرمادية.",
      "第四关拥有二十个史莱姆首领节点。她们生命厚重、攻击较低并会不断再生；沿发光溪流深入森林，最终面对碧露大贤者·涅芙莉。": "في الفصل 4 عشرون عقدة لزعماء السلايم. صحتهم كثيفة وهجومهم منخفض ويتجددون باستمرار؛ اتبع الجدول المتوهج عميقًا في الغابة لتواجه الحكيمة الكبرى نيفري من الندى اللازوردي.",
      "第三关拥有二十个熊族首领节点与一处农舍。沿农田支路调查被占领的村庄，最终面对丰穗战母·布蕾娅。": "في الفصل 3 عشرون عقدة لزعماء الدببة وبيت مزرعة. اتبع دروب المزرعة لتحقق في القرية المحتلة، وفي النهاية واجه أم الحصاد المحاربة بريا.",
      "第二关拥有二十个首领节点。沿着哥布林军团的防线一路推进，最终迎战拥有200生命的翠影女王。": "في الفصل 2 عشرون عقدة زعماء. تقدّم على طول دفاعات جيش الغوبلن وفي النهاية واجه ملكة الظل الزمردي بصحة 200.",
      "在四条前后排战线上部署军队，撕开一路缺口，穿越十三个迷雾森林节点。每一次胜利，都会化为下一次远征的力量。": "انشر جيشك عبر أربعة مسارات قتال بصفوف أمامية وخلفية، وافتح ثغرة واعبر ثلاث عشرة عقدة في الغابة الضبابية. كل نصر يصير قوة للرحلة التالية.",
      "重新开始本关": "إعادة بدء هذا الفصل",
