      "曾任王都护卫队长。野兽接连觉醒后，他认为只守住一座王都远远不够，于是离开王都、集结自己的小队，奔赴各地平定乱局。": "كان قائد الحرس الملكي في العاصمة. حين استيقظت الوحوش واحدًا تلو الآخر، قرر أن حراسة عاصمة واحدة لا تكفي أبدًا، فغادرها وجمع فرقته الخاصة وانطلق لإخماد الاضطرابات في أرجاء البلاد.",
      "生命上限": "الصحة القصوى",
