      "技能最高3级。每赢得一场竞技场比赛，当前装备技能获得2点经验；夺冠还会获得决赛对手的英雄技能。": "تصل المهارات إلى المستوى 3. كل مباراة تفوز بها في الساحة تمنح مهارتك المجهّزة 2 خبرة؛ والفوز بالبطولة يمنحك أيضًا مهارة بطل الخصم النهائي.",
