      "千枝城废墟二十野兽首领路线图": "خريطة طرق عشرين زعيمًا من الوحوش في أطلال الألف غصن",
      "梦幻森林二十史莱姆首领路线图": "خريطة طرق عشرين زعيمًا من السلايم في غابة الأحلام",
      "金麦农场二十首领路线图": "خريطة طرق عشرين زعيمًا في مزرعة القمح الذهبي",
      "哥布林王庭二十节点路线图": "خريطة طرق عشرين عقدة في بلاط الغوبلن",
      "迷雾森林十三节点路线图": "خريطة طرق ثلاث عشرة عقدة في الغابة الضبابية",
      "千枝城古城废墟": "أطلال الألف غصن",
      "梦幻森林": "غابة الأحلام",
      "金麦农场": "مزرعة القمح الذهبي",
      "哥布林王庭": "بلاط الغوبلن",
      "迷雾森林远征": "رحلة الغابة الضبابية",
      "灰狼和其他野兽速度极快，许多单位登场即可攻击。击败全部节点后，魔族联军会在废墟建立据点，之后可以反复挑战强大的军官与魔族军队。": "الذئاب الرمادية والوحوش الأخرى سريعة جدًا، وكثير من الوحدات تستطيع الهجوم فور دخولها. بعد أن تهزم كل العقد، يبني تحالف الشياطين معقلًا في الأطلال، حيث يمكنك تحدي ضباط أقوياء وقوات شيطانية مرارًا.",
      "沿发光溪流与林间小径推进。每个史莱姆首领都会治疗自身与随从；击败节点后开启所有相邻路线，首胜卡牌会在战后揭晓。": "تقدّم على طول الجدول المتوهج ودروب الغابة. كل زعيمة سلايم تشفي نفسها وأتباعها؛ هزيمة عقدة تفتح كل الطرق المجاورة، وتُكشف بطاقات الفوز الأول بعد المعركة.",
      "沿金色路线推进。击败节点后会开启所有相邻路线；抵达农舍旁的节点后，可与留守的农民夫妇交谈。每个首领的首胜奖励会在战后揭晓。": "تقدّم على طول الطريق الذهبي. هزيمة عقدة تفتح كل الطرق المجاورة؛ حين تصل إلى العقدة المجاورة لبيت المزرعة يمكنك التحدث إلى الزوجين المزارعين اللذين بقيا. مكافأة الفوز الأول لكل زعيم تُكشف بعد المعركة.",
      "击败任一节点即可开启相邻路线；翠影女王会在抵达右上方终点后开放。大部分节点由哥布林军团驻守。": "هزيمة أي عقدة تفتح الطرق المجاورة؛ تصبح ملكة الظل الزمردي متاحة حين تصل إلى العقدة الأخيرة في الأعلى يمينًا. معظم العقد يحتلها جيش الغوبلن.",
      "金边节点由更强的敌人驻守；首次击败会获得未知战利品。击败节点后仍可回到岔路挑战相邻路线。": "العقد ذات الإطار الذهبي يحتلها أعداء أقوى؛ الهزيمة الأولى تمنح غنيمة مجهولة. بعد هزيمة عقدة يمكنك العودة إلى المفترق لتحدي الطرق المجاورة.",
      "击败一个节点后，所有相邻的未完成节点都会解锁。战败不会清空本关进度，切换关卡也会分别保存。": "بعد أن تهزم عقدة، تُفتح كل العقد المجاورة غير المكتملة. خسارة معركة لا تمحو تقدّم هذا الفصل، ويُحفظ كل فصل على حدة عند التبديل.",
      "⭐ 本轮": "⭐ هذه الجولة",
      "⚔️ 已完成": "⚔️ مكتملة",
      "🛡️ 失败": "🛡️ فاشلة",
      "退出当前关卡": "مغادرة الفصل",
      "先抵达农舍旁的农田节点。": "اوصل أولًا إلى عقدة الأرض الزراعية المجاورة لبيت المزرعة.",
      "金麦农场 · 留守者的证言": "مزرعة القمح الذهبي · شهادة من بقوا",
      "他们并不要求你放下武器，只希望你在见到丰穗战母之前，先知道这些熊族并未伤害原来的村民。": "لا يطلبان منك إلقاء سلاحك — فقط أن تعرف قبل لقاء أم الحصاد المحاربة أن هذه الدببة لم تؤذِ القرويين الأصليين قط.",
      "我会亲眼判断": "سأحكم بعينيّ",
      "请先完成第五关结局，解锁千枝城魔族重建据点。": "أكمل نهاية الفصل 5 أولًا لفتح معقل الشياطين في مدينة الألف غصن.",
      "极限挑战": "التحدي الأقصى",
      "千枝城驻军暂时退却": "حامية الألف غصن تتراجع",
      "你击退了不可一世的魔族驻军，获得500金币。她们仍会继续重建千枝城，之后仍可再次挑战。": "صددتَ حامية الشياطين المتعجرفة وربحت 500 ذهب. سيواصلون إعادة بناء مدينة الألف غصن، ويمكنك تحديهم مرة أخرى لاحقًا.",
      "返回废墟地图": "العودة إلى خريطة الأطلال",
      "魔族军官守住了据点": "ضباط الشياطين صمدوا في المعقل",
      "20攻/200血的驻军压倒了小队。这场失败不会重置第五关进度，也不会造成额外惩罚。": "حامية الـ20/200 سحقت الفرقة. هذه الهزيمة لن تعيد ضبط تقدّم الفصل 5 ولن تسبب أي عقوبة إضافية.",
      "每一列的前排会保护其身后的后排。": "الصف الأمامي في كل مسار يحمي الصف الخلفي خلفه.",
      "击败前排后，才能普通攻击该列后排。": "لا يمكنك عادةً مهاجمة الصف الخلفي لمسار إلا بعد هزيمة صفه الأمامي.",
      "前后排全部为空时，该路线被突破。": "حين يخلو الصفان، يكون ذلك المسار مخترقًا.",
      "通过突破路线可以直接攻击敌方英雄。": "يمكنك مهاجمة بطل العدو مباشرة عبر مسار مخترق.",
      "你的最大法力不会每回合增加。": "المانا القصوى لديك لا تزداد كل دور.",
      "海港的统领试炼是永久提高最大法力的唯一途径。": "اختبارات القائد في المرفأ هي الطريقة الوحيدة لرفع المانا القصوى بشكل دائم.",
