      "关键物品": "عنصر أساسي",
      "河水中的猩红丝线与古老月辉产生共鸣。它能开启统领试炼第七关。": "خيوط قرمزية في ماء النهر ترنّ مع ضوء قمر قديم. تفتح اختبار القائد 7.",
      "已收入行囊，可用于统领试炼第七关。": "محفوظ في حقيبتك؛ يُستخدم في اختبار القائد 7.",
      "战斗胜利": "النصر",
      "选择一项额外奖励": "اختر مكافأة إضافية واحدة",
      "千枝城的旗帜重新升起": "راية الألف غصن ترتفع من جديد",
      "梦幻森林归于寂静": "غابة الأحلام تصمت",
      "金麦农场的战事落幕": "انتهى القتال في مزرعة القمح الذهبي",
      "哥布林王庭陷落": "سقط بلاط الغوبلن",
      "密林重见曙光": "عاد الفجر إلى الغابة العميقة",
      "你击败银灰狼女猎手后，五位魅魔军官没有继续退避。她们救下狼族首领，以20点攻击的力量击溃小队，并决定在千枝城废墟建立魔族据点、重建这座千年前的共居之城。第五关奖励照常结算，英雄等级上限提升至25级；废墟地图上已经开放可反复挑战的魔族驻军。": "بعد أن تهزم صيادة الذئاب الفضية الرمادية، تكفّ ضابطات الساكوبس الخمس عن التراجع. ينقذن زعيمة الذئاب، ويسحقن الفرقة بـ20 هجوم، ويقررن بناء معقل للشياطين في أطلال الألف غصن لإعادة بناء هذه المدينة التي عاشت فيها الشعوب معًا قبل ألف عام. تُمنح مكافآت الفصل 5 كالمعتاد ويرتفع حد مستوى البطل إلى 25؛ وصارت على خريطة الأطلال حامية شيطانية يمكنك تحديها مرارًا.",
      "你击败了碧露大贤者·涅芙莉，迫使史莱姆族群退回森林深处，并将英雄等级上限提升至20级。": "هزمتَ الحكيمة الكبرى نيفري من الندى اللازوردي، فأجبرت السلايم على التراجع إلى أعماق الغابة، ورفعتَ حد مستوى البطل إلى 20.",
      "你击败了丰穗战母·布蕾娅，完成第三关并解锁东部梦幻森林与英雄20级上限。": "هزمتَ أم الحصاد المحاربة بريا، فأكملت الفصل 3 وفتحت غابة الأحلام الشرقية وحد مستوى البطل 20.",
      "你击败了翠影女王，完成第二关的二十场首领战，并解锁王城南部的金麦农场与英雄15级上限。": "هزمتَ ملكة الظل الزمردي، فأكملت معارك الزعماء العشرين في الفصل 2 وفتحت مزرعة القمح الذهبي جنوب العاصمة وحد مستوى البطل 15.",
      "你击败了森林狼王，并解锁第二关与英雄10级上限。最大法力只在统领试炼中提升。": "هزمتَ ملك ذئاب الغابة، ففتحت الفصل 2 وحد مستوى البطل 10. المانا القصوى لا تزداد إلا عبر اختبارات القائد.",
