      "翠羽射手": "رامية الريش اليشبي",
      "紫晶魔女": "ساحرة الجمشت",
      "晨曦圣女": "قديسة الفجر",
      "裂角蛮王": "أمير الحرب ذو القرن المكسور",
      "银叶游侠": "جوّال الورقة الفضية",
      "银盾骑士": "فارس الدرع الفضي",
      "森灵德鲁伊": "كاهنة البستان",
      "林海边境最年轻的神射手，她的箭能穿过层层枝叶，找到藏在阵后的敌人。": "أصغر رامية على حدود الغابة؛ تنساب سهامها عبر طبقات الأغصان لتجد الأعداء المختبئين خلف الخطوط.",
      "离开法塔独自研究裂隙的魔女，擅长把魔力拆成无数枚难以躲避的飞弹。": "ساحرة تركت برج السحرة لتدرس الصدع وحدها، بارعة في تقسيم المانا إلى قذائف لا تُحصى يصعب تفاديها.",
      "太阳神殿派往前线的圣女，相信每一名士兵都值得再站起来一次。": "قديسة أرسلها معبد الشمس إلى الجبهة، تؤمن بأن كل جندي يستحق أن ينهض مرة أخرى.",
      "北地部族的蛮王，以自己的鲜血点燃战士的怒火。": "أمير حرب من قبائل الشمال يوقد غضب محاربيه بدمه.",
      "月林巡林员的首领，总能让敌人在树影里看到不该出现的弓手。": "قائد جوّالي غابة القمر، يجعل الأعداء دائمًا يلمحون رماة في الظلال حيث لا ينبغي أن يكون أحد.",
      "王都晨辉骑士团的老兵，他的盾阵从未在他面前后退一步。": "محارب قديم من فرقة ضوء الفجر في العاصمة؛ جدار دروعه لم يتراجع خطوة قط.",
      "古林之心孕育的德鲁伊，她种下的每一株幼苗都会长成守护森林的古树。": "كاهنة طبيعة وُلدت من قلب البستان العتيق؛ كل شتلة تزرعها تكبر لتصير شجرة عتيقة تحرس الغابة.",
      "穿林箭": "السهم الخارق",
      "奥术飞弹": "القذائف السحرية",
      "晨曦复苏": "إحياء الفجر",
      "血怒狂击": "هيجان الدم",
      "林间伏兵": "كمين الغابة",
      "圣盾壁垒": "جدار الدروع",
      "萌芽古树": "الشجرة العتيقة النابتة",
      "无视前排保护，对任意一个敌方随从造成{0}点伤害；若击杀目标，抽1张牌。": "متجاهلًا حماية الصف الأمامي، ألحق {0} ضرر بأي تابع عدو؛ إن مات، اسحب بطاقة واحدة.",
      "发射{0}枚奥术飞弹，每枚随机对一个敌方随从或敌方英雄造成1点伤害。": "أطلق {0} قذائف سحرية، تُلحق كل منها 1 ضرر بتابع عدو عشوائي أو ببطل العدو.",
      "使所有己方随从恢复至满生命，并为英雄恢复{0}点生命。": "أعد جميع الأتباع الصديقة إلى صحتها الكاملة واستعد {0} صحة لبطلك.",
      "英雄失去2点生命，使一个己方随从本回合获得+{0}攻击，并可以立即再次攻击。": "يفقد بطلك 2 صحة؛ ويكسب تابع صديق +{0} هجوم هذا الدور ويستطيع الهجوم مجددًا فورًا.",
      "在后排召唤一个{0}攻/{1}血的远程林影弓手，它可以立即攻击随从。": "استدعِ رامي ورقة الظل بعيد المدى {0}/{1} في الصف الخلفي؛ يستطيع مهاجمة الأتباع فورًا.",
      "所有己方前排随从永久获得+{0}生命；若前排为空，则召唤一个0攻/{1}血的圣盾卫士。": "تكسب جميع الأتباع الصديقة في الصف الأمامي +{0} صحة بشكل دائم؛ إن كان صفك الأمامي فارغًا، استدعِ حارس الدرع 0/{1}.",
      "召唤一个{0}攻/{1}血的古树幼苗；它在你每回合开始时永久获得+1/+1。": "استدعِ شتلة عتيقة {0}/{1}؛ في بداية كل دور من أدوارك تكسب +1/+1 بشكل دائم.",
