      "晨曦照亮战线：随从共恢复{0}点生命，英雄恢复{1}点生命。": "الفجر يضيء خط القتال: تستعيد الأتباع {0} صحة إجمالًا، ويستعيد بطلك {1} صحة.",
      "{0}陷入血怒，本回合攻击力提升至{1}，可以立即攻击。": "{0} يدخل هيجان الدم: يرتفع الهجوم إلى {1} هذا الدور ويستطيع الهجوم فورًا.",
      "{0}陷入血怒，本回合攻击力提升至{1}。": "{0} يدخل هيجان الدم: يرتفع الهجوم إلى {1} هذا الدور.",
      "圣盾壁垒加固前排：{0}个随从永久获得+{1}生命。": "جدار الدروع يحصّن الصف الأمامي: {0} من الأتباع يكسبون +{1} صحة بشكل دائم.",
