      "第二关起击败的首领，其首杀奖励卡要与牢里的本人结缘（好感度{0}）后才能出战；继续投喂，每{1}点好感升一级（最高{2} Lv{3}），结缘后每高一级：随从+{4}攻击、+{5}生命，法术效果提升{6}级。最终首领的卡牌要等本关全部在押首领结缘才能使用，等级取其中最低的一位。每名首领每天（现实{7}分钟）只能投喂一次，距离新的一天还有{8}。背包里共有 {9} 份食物。": "بدءًا من الفصل 2، لا يمكن استخدام بطاقة مكافأة القتل الأول لزعيم مهزوم إلا بعد أن ترتبط بذلك الزعيم في السجن (ألفة {0}). واصل الإطعام لتكسب مستوى كل {1} ألفة (حتى {2} Lv{3}). كل مستوى فوق الارتباط يمنح الأتباع +{4} هجوم و+{5} صحة، والتعاويذ +{6} مستويات تأثير. بطاقة الزعيم النهائي لا تُفتح إلا حين يرتبط كل زعماء ذلك الفصل الأسرى، وتأخذ أدنى مستوياتهم. يمكن إطعام كل زعيم مرة في اليوم ({7} دقيقة حقيقية)؛ يبدأ اليوم التالي بعد {8}. لديك {9} عنصر طعام في حقيبتك.",
